            new Quote { Id = "https://ar.wikiquote.org/wiki/المتنبي", Text = "وفي الجهل قبل الموت موت لأهله\nفأجسامهم قبل القبور قبور", Author = "المتنبي" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/المتنبي", Text = "وأن امرأ لم يحي بالعلم ميت\nفليس له حتى النشور نشور", Author = "المتنبي" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/المتنبي", Text = "لولا المشقة ساد الناس كلهم\nالجود يفقر والإقدام قتال", Author = "المتنبي" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/المتنبي", Text = "أنا الذي نظر الأعمى إلى أدبي\nوأسعمت كلماتي من به صمم", Author = "المتنبي" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/المتنبي", Text = "الخيل والليل والبيداء تعرفني\nوالسيف والرمح والقرطاس والقلم", Author = "المتنبي" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/المتنبي", Text = "فإذا أتتك مذمتي من ناقص\nفهي الشهادة لي بأني كامل", Author = "المتنبي" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/المتنبي", Text = "على قدر أهل العزم تأتي العزائم\nوتأتي على قدر الكرام المكارم", Author = "المتنبي" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/المتنبي", Text = "وتعظم في عين الصغير صغارها\nوتصغر في عين العظيم العظائم", Author = "المتنبي" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/المتنبي", Text = "أغاية الدين أن تحفوا شواربكم\nيا أمة ضحكت من جهلها الأمم", Author = "المتنبي" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/المتنبي", Text = "إنما الناس بالملوك وما\nتفلح عرب ملوكها عجم", Author = "المتنبي" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/المتنبي", Text = "لا أدب عندهم ولا حسب\nولا عهود لهم ولا ذمم", Author = "المتنبي" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/المتنبي", Text = "بكل أرض وطئتها أمم\nترعى بعبد كأنها غنم", Author = "المتنبي" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/المتنبي", Text = "يستخشين الخز حين يلمسه\nوكان يبري بظفره القلم", Author = "المتنبي" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/المتنبي", Text = "ومثلك يؤتى من بلاد بعيدة\nليضحك ربات الحداد البواكيا", Author = "المتنبي" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/المتنبي", Text = "إذا رأيت نيون الليث بارزة\nفلا تظنن أن الليث يبتسم", Author = "المتنبي" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/المتنبي", Text = "لا تحقرن صغيرًا في مخاصمة\nإن البعوضة تدمي مقلة الأسد", Author = "المتنبي" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/المتنبي", Text = "وما انتفاع أخي الدنيا بناظره\nإذا استوت عنده الأنوار والظلم", Author = "المتنبي" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/المتنبي", Text = "ومن تفكر في الدنيا ومهجته\nأقامه الفكر بين العجز والتعب", Author = "المتنبي" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/المتنبي", Text = "فما ينفع الأسد الحياء من الطوى\nولا تتقى حتى تكن ضواريا", Author = "المتنبي" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/المتنبي", Text = "جوعان يأكل من زادي ويمسكني\nلكي يقال عظيم القدر مقصود", Author = "المتنبي" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/المتنبي", Text = "ذو العقل يشقى في النعيم بعقله\nوأخو الجهالة في الشقاوة ينعم", Author = "المتنبي" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/المتنبي", Text = "تريدين لقيان المعالي رخيصة\nولا بد دون الشهد من إبر النحل", Author = "المتنبي" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/المتنبي", Text = "ما كل ما يتمناه المرء يدركه\nتجري الرياح بما لا تشتهي السفن", Author = "المتنبي" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/المتنبي", Text = "إذا أنت أكرمت الكريم ملكته\nوإن أنت أكرمت اللئيم تمردا", Author = "المتنبي" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/المتنبي", Text = "وعذلت أهل العشق حتى ذقته\nفعجبت كيف يموت من لا يعشق", Author = "المتنبي" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/المتنبي", Text = "وعرفت ذنبي في الهوى أنني عيرت\nهم فلقيت منه ما لقوا", Author = "المتنبي" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/المتنبي", Text = "ما باله لاحظته فتضرّجت\nوجناته وفؤادي المجروح", Author = "المتنبي" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/المتنبي", Text = "ورمى وما رمته يداه فأصابني\nسهم يعذب والسهام تريح", Author = "المتنبي" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/المتنبي", Text = "بفرع يعيد الليل والصبح نير\n ووجه يعيد الصبح والليل مظلم", Author = "المتنبي" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/المتنبي", Text = "ومتى تزُر قوم من تهوى زيارتها\nلا يتحفوك بغير البيض والأسل", Author = "المتنبي" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/المتنبي", Text = "والهجر أقـتل لي مما أراقبه\nأنا الغريق فما خوفي من البلل", Author = "المتنبي" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/المتنبي", Text = "لك يا منازل في القلوب منازل\nأقفـرت أنت وهن منك أواهـل", Author = "المتنبي" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/المتنبي", Text = "وقيدت نفسي في ذراك محبة\nومن وجد الإحسان قيداً تقيدا", Author = "المتنبي" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/المتنبي", Text = "إذا الجود لم يرزق خلاصا من الأذى\nفلا الحمد مكسوبا ولا المال باقيا", Author = "المتنبي" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/المتنبي", Text = "عش عزيزا أو مت وأنت كريم\nبين طعن القنا وخفق البنود", Author = "المتنبي" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/المتنبي", Text = "فاظلب العز في لظى ودع الذل\nولو كان في جنان الخلود", Author = "المتنبي" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/المتنبي", Text = "وزائرتي كأن بها حياء\nفليس تزور إلا في الظلام", Author = "المتنبي" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/المتنبي", Text = "بذلت لها المطارف والحشايا\nفعافتها وباتت في عظامي", Author = "المتنبي" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/المتنبي", Text = "من يهـن يسهـل الهـوان عليـه\nما لجرح بميـت إيـلام", Author = "المتنبي" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/المتنبي", Text = "إذا غامرت في شرف مروم\nفلا تقنع بما دون النجوم", Author = "المتنبي" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/المتنبي", Text = "إذا أنت أكرمت الكريم ملكته\nوإن أنت أكرمت اللئيم تمردا", Author = "المتنبي" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/المتنبي", Text = "وإذا لم يكن من الموت بدٌ\nفمن العجز أن تموت جبانا", Author = "المتنبي" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/المتنبي", Text = "أعز مكان في الدنى سرج سابح\nوخير جليس في الأنام كتاب", Author = "المتنبي" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/المتنبي", Text = "خير المحادث والجليس كتاب\nتخلو به إن ملّك الأصحاب", Author = "المتنبي" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/المتنبي", Text = "الرأي قبل شجاعة الشجعان\nهو أول وهي المحل الثاني", Author = "المتنبي" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/المتنبي", Text = "إذا ساء فعل المرء ساءت ظنونه\n وصدق ما يعتدّه من توهم", Author = "المتنبي" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/المتنبي", Text = "حرّض بنيك على الآداب في الصّغر\n كيما تقرّ بهم عيناك في الكبر", Author = "المتنبي" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/المتنبي", Text = "شر البلاد مكان لا صديق به\n وشر ما يكسب الإنسان ما يصم", Author = "المتنبي" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/المتنبي", Text = "ومن نكد الدّنيا على الحرّ أن يرى\n عدوًا له ما من صداقته بد", Author = "المتنبي" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/المتنبي", Text = "ومن العداوة ما ينالك نفعه\n ومن الصداقة ما يضر ويؤلم", Author = "المتنبي" },
